<?php require_once __DIR__.'/../includes/auth.php'; require_role('DONOR');
$d=my_donor($pdo); $validTypes=['VOLUNTARY','CAMPAIGN','WALK_IN','EMERGENCY']; $t=get('type'); $f=get('from'); $to=get('to'); $q=get('q');
if(!in_array($t,$validTypes,true)) $t='';
$validDate=fn($x)=>$x===''||(bool)(DateTime::createFromFormat('Y-m-d',$x) && DateTime::createFromFormat('Y-m-d',$x)->format('Y-m-d')===$x);
if(!$validDate($f)) $f=''; if(!$validDate($to)) $to=''; if($f && $to && $f>$to){$tmp=$f;$f=$to;$to=$tmp;}
$sql='SELECT n.*,o.organization_name,c.campaign_name FROM donations n JOIN healthcare_organizations o ON o.organization_id=n.organization_id LEFT JOIN donation_campaigns c ON c.campaign_id=n.campaign_id WHERE n.donor_id=?'; $p=[$d['donor_id']];
if($t){$sql.=' AND n.donation_type=?';$p[]=$t;} if($f){$sql.=' AND DATE(n.donation_date)>=?';$p[]=$f;} if($to){$sql.=' AND DATE(n.donation_date)<=?';$p[]=$to;}
if($q!==''){$sql.=' AND (o.organization_name LIKE ? OR c.campaign_name LIKE ?)';$p[]="%$q%";$p[]="%$q%";}
$s=$pdo->prepare($sql.' ORDER BY n.donation_date DESC'); $s->execute($p); $rows=$s->fetchAll();
$cnt=0;$units=0; foreach($rows as $x) if($x['status']==='COMPLETED'){ $cnt++; $units+=(int)$x['units_donated']; }
$rs='SELECT m.*,r.blood_group,r.urgency,r.location,o.organization_name FROM donor_matches m JOIN emergency_requests r USING(request_id) JOIN healthcare_organizations o ON o.organization_id=r.organization_id WHERE m.donor_id=?'; $rp=[$d['donor_id']];
if($q!==''){$rs.=' AND (o.organization_name LIKE ? OR r.location LIKE ?)';$rp[]="%$q%";$rp[]="%$q%";}
$r=$pdo->prepare($rs.' ORDER BY m.matched_at DESC'); $r->execute($rp); $responses=$r->fetchAll();
$title='Donation & Response History'; $page_intro='Your recorded donations and responses to emergency requests.'; require '../includes/header.php'; ?>
<div class="grid"><div class="stat"><b><?= $cnt ?></b><span>Donations (this view)</span></div><div class="stat"><b><?= $units ?></b><span>Units donated (this view)</span></div><div class="stat"><b><?= h($d['last_donation_date']?:'—') ?></b><span>Last donation</span><small class="stat-note">Date you declared at registration. The table below lists only donations recorded by a healthcare organization.</small></div><div class="stat"><b><?= count($responses) ?></b><span>Emergency responses</span></div></div>
<div class="card"><h2>Donation history</h2><p class="muted">Only donations recorded by a healthcare organization appear here. If a record is missing or incorrect, contact that organization.</p>
<form class="filter"><input name="q" placeholder="Search organization or campaign" value="<?= h($q) ?>"><select name="type"><option value="">All donation types</option><?php foreach($validTypes as $x): ?><option value="<?= h($x) ?>" <?= $t===$x?'selected':'' ?>><?= h(ucwords(strtolower(str_replace('_',' ',$x))) ) ?></option><?php endforeach; ?></select><label class="dl">From date <input type="date" name="from" value="<?= h($f) ?>"></label><label class="dl">To date <input type="date" name="to" value="<?= h($to) ?>"></label><button class="btn">Filter</button> <a class="btn alt" href="donation_history.php">Reset</a></form>
<div class="tw"><table><thead><tr><th>Date</th><th>Organization</th><th>Type</th><th>Campaign</th><th>Blood group</th><th>Units</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $x): ?><tr><td><?= h($x['donation_date']) ?></td><td><?= h($x['organization_name']) ?></td><td><?= h($x['donation_type']) ?></td><td><?= h($x['campaign_name']?:'—') ?></td><td><?= h($x['blood_group']) ?></td><td><?= h($x['units_donated']) ?></td><td><?= badge($x['status']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7">No donation records match these filters.</td></tr><?php endif; ?></tbody></table></div></div>
<h2>Emergency response history</h2><div class="tw"><table><thead><tr><th>Request</th><th>Organization</th><th>Group needed</th><th>Urgency</th><th>Location</th><th>Notified</th><th>Responded</th><th>Status</th></tr></thead><tbody><?php foreach($responses as $x): ?><tr><td>#<?= (int)$x['request_id'] ?></td><td><?= h($x['organization_name']) ?></td><td><?= h($x['blood_group']) ?></td><td><?= badge($x['urgency']) ?></td><td><?= h($x['location']) ?></td><td><?= h($x['matched_at']) ?></td><td><?= h($x['responded_at']??'—') ?></td><td><?= badge($x['status']) ?></td></tr><?php endforeach; ?><?php if(!$responses): ?><tr><td colspan="8">No emergency responses recorded yet.</td></tr><?php endif; ?></tbody></table></div>
<?php require '../includes/footer.php'; ?>
